privacy=subhero('Your privacy.','How this website handles your information.')+'''<section class="container section privacy-layout"><nav aria-label="Privacy topics"><a href="#enquiry-information">Enquiry information</a><a href="#external-services">External services</a><a href="#medical-information">Sensitive information</a><a href="#website-content">Website content</a></nav><div class="prose"><section id="enquiry-information"><h2>Your enquiry stays in your browser.</h2><p>The appointment enquiry form does not send, save or upload the information you enter. It prepares text that you can choose to send through your email app or Instagram.</p></section><section id="external-services"><h2>When you use another service.</h2><p>WhatsApp, email, Instagram and Google Maps have their own privacy policies. Clicking a contact link opens the relevant service; it does not send a message automatically. Fonts are loaded from Google Fonts. This website does not use analytics or advertising cookies.</p></section><section id="medical-information"><h2>Keep sensitive details for the clinic.</h2><p>Please do not include medical records or sensitive health information in the form. Contact the clinic directly about clinical questions and the appropriate way to share records. An enquiry does not confirm an appointment.</p></section><section id="website-content"><h2>About our photographs and guides.</h2><p>Photography is illustrative and was supplied by the clinic for this website. The models shown are not identified as actual clinic staff or patients. Treatment pages introduce the clinic’s services and suggest discussion questions; they do not replace an individual dental assessment.</p></section></div></section>'''
pages={'index.html':('Home',home),'about.html':('About us',about),'treatments.html':('Treatments',treatments),'contact.html':('Contact',contact),'privacy.html':('Privacy',privacy)}
for slug,title,sub,desc,photo in services:
 category=categories[slug];group_index=group_names.index(category)
 related=[s for s in services if categories[s[0]]==category and s[0]!=slug][:4]
 if not related:related=[s for s in services if s[0] in ['general-dental-procedures','dental-checkups']]
 body=subhero(title,desc,photo)+f'''<section class="container section treatment-discussion"><div class="treatment-intro"><span class="eyebrow">{category}</span><h2>{sub}</h2><p>Use your visit to explore {title.lower()} in the context of your own dental health, priorities and preferences. The questions below can help you prepare for that conversation.</p><a class="category-back" href="treatments.html#{group_ids[group_index]}">View our {category.lower()} services</a></div><aside class="enquiry-card"><span class="eyebrow">Talk to the clinic</span><h3>Enquire about<br>{title.lower()}.</h3><p>Contact our team to discuss a consultation and appointment availability.</p>{button('Enquire about this treatment','contact.html?service='+quote(title))}<a class="phone-link" href="tel:+919496801445">+91 9496 801 445</a></aside><div class="discussion-main">{questions_section('A useful conversation starts here.',questions[slug])}<div class="decision-note"><h3>Decide with a clear understanding.</h3><p>Ask your dentist to explain the findings, suitable options, likely visits and an individual estimate before agreeing on a plan. Suitability and treatment outcomes vary.</p></div></div></section><section class="related-care"><div class="container"><div class="related-heading"><span class="eyebrow">Continue exploring</span><h2>Related care to consider.</h2><p>Other services in this area of dentistry.</p></div><div class="related-links">{''.join(f'<a href="{r[0]}.html"><h3>{r[1]}</h3><p>{r[2]}</p><span>Explore this service</span></a>' for r in related)}</div></div></section>'''
 pages[slug+'.html']=(title,body)
for file,(title,body) in pages.items():
 (d/file).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#12498e"><title>{title+' | ' if title!='Home' else ''}Cosmopolitan Dental Care</title><meta name="description" content="Specialized dentistry and personalised care in Moozhikal, Kozhikode. Explore all our dental treatments and call +91 9496 801 445."><link rel="canonical" href="https://dental.zedqhub.com/{'' if file=='index.html' else file}"><meta property="og:title" content="Cosmopolitan Dental Care"><meta property="og:description" content="Your smile. Our priority. Thoughtful dentistry with a gentle touch."><meta property="og:type" content="website"><link rel="icon" href="assets/logo-symbol.png" type="image/png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css?v=blue-care6"><script src="app.js?v=blue-care6" defer></script></head><body class="page-{file.removesuffix('.html')}">{header('Treatments' if file.replace('.html','') in [s[0] for s in services] else title)}<main id="main">{body}</main>{footer()}</body></html>''')
print('Built',len(pages),'pages')
